49	// Budget figures are shown with thousands separators (e.g. $1,000.00) so larger amounts stay
50	// readable at a glance.
51	function moneyGrouped(amount: number): string {
52	  return `$${Number(amount).toLocaleString('en-US', {
53	    minimumFractionDigits: 2,
54	    maximumFractionDigits: 2,
55	  })}`;
56	}
