64	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
65	// many, price each), the total worked out for you, and a form to add another line. Each line can be
66	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
67	// own line-item state, scoped to the one invoice it is showing.
68	function InvoiceDetail({
69	  invoiceId,
70	  onChange,
71	  onClose,
72	}: {
73	  invoiceId: number;
74	  onChange: () => void;
75	  onClose: () => void;
76	}) {
77	  const [items, setItems] = useState<EditItem[]>([]);
78	  const [description, setDescription] = useState('');
79	  const [qty, setQty] = useState('');
