307	// Which lifecycle actions an invoice offers depends on where it is in its lifecycle: a draft can be
308	// sent, a sent invoice can be marked paid. Collecting the mapping here keeps the row markup flat and
309	// gives one obvious place to add a new lifecycle action.
310	function InvoiceActions({
311	  invoice,
312	  onOpen,
313	  onSend,
314	  onPay,
315	  onCancel,
316	}: {
317	  invoice: Invoice;
318	  onOpen: () => void;
319	  onSend: () => void;
320	  onPay: () => void;
321	  onCancel: () => void;
322	}) {
323	  return (
324	    <>
325	      <button data-testid={`invoice-open-${invoice.id}`} onClick={onOpen}>
326	        Open
327	      </button>
328	      {invoice.status === 'DRAFT' && (
329	        <button data-testid={`invoice-send-${invoice.id}`} onClick={onSend}>
330	          Send
331	        </button>
332	      )}
333	      {invoice.status === 'SENT' && (
334	        <button data-testid={`invoice-pay-${invoice.id}`} onClick={onPay}>
335	          Mark paid
336	        </button>
337	      )}
338	      {invoice.status === 'SENT' && (
339	        <button data-testid={`invoice-cancel-${invoice.id}`} onClick={onCancel}>
340	          Cancel
341	        </button>
342	      )}
343	    </>
344	  );
345	}
