347	// The invoices raised against a project: what they add up to, a form to raise another, and a drill-in
348	// to each invoice's line items and payments. Owns its own invoice state, scoped to the one project.
349	// Whenever the invoices change (a new one raised, a status moved, a line item edited) the owner is
350	// told so figures derived from them — the budget's invoiced/remaining — can be refreshed.
351	function ProjectInvoices({
352	  projectId,
353	  onInvoicesChanged,
354	}: {
355	  projectId: number;
356	  onInvoicesChanged: () => void;
357	}) {
358	  const [invoices, setInvoices] = useState<Invoice[]>([]);
359	  const [amount, setAmount] = useState('');
360	  const [amountError, setAmountError] = useState('');
361	  const [sortByDue, setSortByDue] = useState(false);
362	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
363	
364	  async function load() {
365	    const res = await fetch(`/api/invoices?projectId=${projectId}`);
366	    setInvoices(await res.json());
367	    onInvoicesChanged();
368	  }
369	
370	  useEffect(() => {
371	    void load();
372	  }, [projectId]);
373	
374	  async function submit(e: React.FormEvent) {
375	    e.preventDefault();
376	    const value = Number(amount);
377	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
378	      setAmountError('Amount must be more than zero');
379	      return;
380	    }
381	    setAmountError('');
382	    await fetch('/api/invoices', {
383	      method: 'POST',
384	      headers: { 'Content-Type': 'application/json' },
385	      body: JSON.stringify({ projectId, amount: value }),
386	    });
387	    setAmount('');
388	    await load();
389	  }
390	
391	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
392	  // routing them through one place means a new action is one more call site, not new plumbing.
393	  async function transition(id: number, action: 'send' | 'pay' | 'cancel') {
394	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
395	    await load();
396	  }
397	
398	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
399	  const shownInvoices = sortByDue
400	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
401	    : invoices;
402	
403	  return (
404	    <>
405	      <form data-testid="invoice-form" onSubmit={submit}>
406	        <input
407	          data-testid="invoice-form-amount"
408	          placeholder="Amount"
409	          value={amount}
410	          onChange={(e) => setAmount(e.target.value)}
411	        />
412	        <button data-testid="invoice-form-submit" type="submit">
413	          Add invoice
414	        </button>
415	        {amountError && (
416	          <p data-testid="invoice-form-amount-error" role="alert">
417	            {amountError}
418	          </p>
419	        )}
420	      </form>
421	
422	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
423	        Sort by due date
424	      </button>
425	
426	      {openInvoiceId === null ? (
427	        <>
428	          <table data-testid="project-invoices-table">
429	            <tbody>
430	              {shownInvoices.map((inv) => (
431	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
432	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
433	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
434	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
435	                  <td data-testid="invoice-due">{inv.dueDate}</td>
436	                  <td data-testid="invoice-status">{inv.status}</td>
437	                  <td>
438	                    <InvoiceActions
439	                      invoice={inv}
440	                      onOpen={() => setOpenInvoiceId(inv.id)}
441	                      onSend={() => transition(inv.id, 'send')}
442	                      onPay={() => transition(inv.id, 'pay')}
443	                      onCancel={() => transition(inv.id, 'cancel')}
444	                    />
445	                  </td>
446	                </tr>
447	              ))}
448	            </tbody>
449	          </table>
450	
451	          <p data-testid="project-invoices-total">{money(total)}</p>
452	        </>
453	      ) : (
454	        <InvoiceDetail
455	          invoiceId={openInvoiceId}
456	          onChange={load}
457	          onClose={() => setOpenInvoiceId(null)}
458	        />
459	      )}
460	    </>
461	  );
462	}
