189	    /** The list of fixture rows under {@code key}, or an empty list when the fixture omits it. */
190	    @SuppressWarnings("unchecked")
191	    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
192	        return (List<Map<String, Object>>) fixture.getOrDefault(key, List.of());
193	    }
194	
195	    /** A fixture id column: JSON numbers arrive as {@link Number}, the tables use {@code BIGINT}. */
196	    private static long id(Map<String, Object> row, String key) {
197	        return ((Number) row.get(key)).longValue();
198	    }
199	
200	    private static Double asDouble(Object value) {
201	        return value == null ? null : ((Number) value).doubleValue();
202	    }
203	
204	    private static String asText(Object value) {
205	        return value == null ? null : value.toString();
206	    }
207	
208	    /**
209	     * Builds an {@code INSERT} whose column set is decided per row, so a fixture can omit a column
210	     * and let the table's own default apply (a bare null would trip a NOT NULL column). Required
211	     * columns are added with {@link #set}; optional ones with {@link #setIfPresent}.
212	     */
213	    private final class Insert {
214	        private final String table;
215	        private final StringBuilder cols = new StringBuilder();
216	        private final StringBuilder marks = new StringBuilder();
217	        private final List<Object> args = new ArrayList<>();
218	
219	        Insert(String table) {
220	            this.table = table;
221	        }
222	
223	        Insert set(String column, Object value) {
224	            if (cols.length() > 0) {
225	                cols.append(", ");
226	                marks.append(", ");
227	            }
228	            cols.append(column);
229	            marks.append("?");
230	            args.add(value);
231	            return this;
232	        }
233	
234	        Insert setIfPresent(String column, Object value) {
235	            return value == null ? this : set(column, value);
236	        }
237	
238	        void run() {
239	            jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")",
240	                    args.toArray());
241	        }
242	    }
243	}
